using System.Net.Http.Headers;
using Apogeu.Security.Tests.Support;
using Apogeu.Wallet.Contracts;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace Apogeu.Wallet.Tests.Support;

/// <summary>
/// The real Host in memory (WebApplicationFactory) in Development on real PostgreSQL and Redis, configured only with values
/// generated by the test (ADR-0014): one demo API key, the player-session signing key and the game base URL. The hosted
/// services of the Operators (migrations and Development seed: demo operator and BRL limits of SPEC-0020) and Wallet
/// modules stay, so the schemas are created through the real path, and so does the Host's messaging (the
/// <c>HostedMessaging</c> of ServiceDefaults, ADR-0028), which runs the scheduled Wolverine messages of the seamless resend
/// (SPEC-0046); the other modules' hosted services are removed.
/// </summary>
internal sealed class WalletApiHost : IAsyncDisposable
{
    public static readonly Uri BaseAddress = new("https://api.apogeu.test");

    /// <summary>Assembly of the Host's messaging lifecycle (Wolverine), kept in the test host.</summary>
    private const string ServiceDefaultsAssembly = "Apogeu.ServiceDefaults";

    private readonly WebApplicationFactory<Program> _factory;
    private readonly string _signingKey;

    private WalletApiHost(WebApplicationFactory<Program> factory, string signingKey, string database)
    {
        _factory = factory;
        _signingKey = signingKey;
        Database = database;
    }

    /// <summary>Connection string of the database of this host (another host can be started on it: a restart, SPEC-0046 IT-04).</summary>
    public string Database { get; }

    /// <summary>The services of the running host.</summary>
    public IServiceProvider Services => _factory.Services;

    public static async Task<WalletApiHost> StartAsync(string postgresServerConnectionString, string redisConnectionString, CancellationToken cancellationToken)
    {
        var database = await TestDatabase.CreateAsync(postgresServerConnectionString, cancellationToken).ConfigureAwait(false);
        return await StartOnDatabaseAsync(database, redisConnectionString, configureServices: null).ConfigureAwait(false);
    }

    /// <summary>
    /// The Host on the existing <paramref name="database"/>, with <paramref name="configureServices"/> applied over the
    /// application services (for example the operator wallet settings of SPEC-0046 and a log capture).
    /// </summary>
    public static Task<WalletApiHost> StartOnDatabaseAsync(string database, string redisConnectionString, Action<IServiceCollection>? configureServices)
    {
        var key = TestApiKey.Generate();
        var signingKey = WalletSessions.NewSigningKey();

        var factory = new WebApplicationFactory<Program>().WithWebHostBuilder(host =>
        {
            host.UseEnvironment("Development");
            host.UseSetting("ConnectionStrings:apogeu", database);
            host.UseSetting("ConnectionStrings:redis", redisConnectionString);
            host.UseSetting("Operators:GameBaseUrl", "https://game.apogeu.test");
            host.UseSetting("Operators:Demo:ApiKeys:0:Id", key.Id);
            host.UseSetting("Operators:Demo:ApiKeys:0:Secret", key.Secret);
            host.UseSetting(WalletSessions.SettingName, signingKey);
            host.ConfigureTestServices(services =>
            {
                var otherModules = services
                    .Where(d => d.ServiceType == typeof(IHostedService)
                        && d.ImplementationType?.Assembly.GetName().Name is { } assembly
                        && assembly.StartsWith("Apogeu.", StringComparison.Ordinal)
                        && !string.Equals(assembly, ServiceDefaultsAssembly, StringComparison.Ordinal)
                        && !assembly.StartsWith("Apogeu.Operators.", StringComparison.Ordinal)
                        && !assembly.StartsWith("Apogeu.Wallet.", StringComparison.Ordinal))
                    .ToList();
                foreach (var descriptor in otherModules)
                {
                    services.Remove(descriptor);
                }

                configureServices?.Invoke(services);
            });
        });

        try
        {
            // Starts the host now: the migrations and the Development seed run here.
            _ = factory.Server;
        }
        catch
        {
            factory.Dispose();
            throw;
        }

        return Task.FromResult(new WalletApiHost(factory, signingKey, database));
    }

    /// <summary>A client with the session of <paramref name="playerId"/> (mode <paramref name="mode"/>, demo by default) as bearer.</summary>
    public HttpClient CreateClient(string playerId, string mode = "demo")
    {
        var client = CreateAnonymousClient();
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", WalletSessions.Issue(_signingKey, playerId, mode));
        return client;
    }

    /// <summary>A client without a session.</summary>
    public HttpClient CreateAnonymousClient() =>
        _factory.CreateClient(new WebApplicationFactoryClientOptions { BaseAddress = BaseAddress, AllowAutoRedirect = false });

    /// <summary>Runs <paramref name="action"/> with the Host's <see cref="IOperatorWallet"/>, in a DI scope of its own.</summary>
    public async Task<T> WithWalletAsync<T>(Func<IOperatorWallet, Task<T>> action)
    {
        ArgumentNullException.ThrowIfNull(action);
        var scope = _factory.Services.CreateAsyncScope();
        await using (scope.ConfigureAwait(false))
        {
            return await action(scope.ServiceProvider.GetRequiredService<IOperatorWallet>()).ConfigureAwait(false);
        }
    }

    public ValueTask DisposeAsync() => _factory.DisposeAsync();
}
